-- calc_clients_avg_goal_progress
-- Field: Clients.AvgGoalProgress
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_clients_avg_goal_progress(p_clients_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COALESCE(AVG((((SELECT (COALESCE((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_goals_avg_score_achieved(erb_r1.goals_id)) AS v OFFSET 0) __safe_numeric), 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (erb_r1.target_score) AS v OFFSET 0) __safe_numeric), 0), 0))) AS v OFFSET 0) __safe_numeric), 0) * COALESCE(100, 0)), 0))::numeric))::numeric)::numeric), 0) FROM goals erb_r1 WHERE client = p_clients_id))::numeric;
$$ LANGUAGE sql STABLE;

