-- calc_goals_progress_pct
-- Field: Goals.ProgressPct
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_goals_progress_pct(p_goals_id TEXT)
RETURNS NUMERIC AS $$
  SELECT (COALESCE((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_goals_avg_score_achieved(p_goals_id)) AS v OFFSET 0) __safe_numeric), 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT target_score FROM goals WHERE goals_id = p_goals_id)) AS v OFFSET 0) __safe_numeric), 0), 0))) AS v OFFSET 0) __safe_numeric), 0) * COALESCE(100, 0)), 0))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_goals_remaining_gap
